# Suggested hardened version of `app.js`

This example keeps the app simple but adds common protections.

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

const PORT = Number(process.env.PORT) || 3000;
const API_TOKEN = process.env.API_TOKEN;

app.disable('x-powered-by');

app.use(helmet());

app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: false, limit: '100kb' }));

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests' }
});

app.use(generalLimiter);

function requireAuth(req, res, next) {
  if (!API_TOKEN) {
    console.error('API_TOKEN is not configured');
    return res.status(500).json({ error: 'Server configuration error' });
  }

  const authHeader = req.get('Authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.slice('Bearer '.length);

  if (token !== API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  next();
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', requireAuth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  console.error(err);

  res.status(500).json({
    error: 'Internal server error'
  });
});

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
```

Required packages:

```bash
npm install helmet express-rate-limit
```

Run with:

```bash
API_TOKEN='replace-with-a-long-random-token' PORT=3000 node app.js
```

