For endpoints that need email addresses, add authorization checks:

```js
function requireAdmin(req, res, next) {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  next();
}

app.get('/users', requireApiKey, requireAdmin, (req, res) => {
  res.json(users);
});
