# Suggested Hardened Version of `app.js`

Below is a more secure version while keeping the app simple.

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

app.disable('x-powered-by');

app.use(helmet());

app.use(express.json({ limit: '100kb' }));

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later' },
});

app.use(generalLimiter);

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.slice('Bearer '.length);

  if (!process.env.API_TOKEN || token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid or insufficient credentials' });
  }

  next();
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', requireAuth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  if (process.env.NODE_ENV !== 'test') {
    console.error({
      message: err.message,
      stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
      path: req.path,
      method: req.method,
    });
  }

  res.status(err.status || 500).json({
    error: err.status ? err.message : 'Internal server error',
  });
});

module.exports = app;
```

Then move server startup to `server.js`:

```js
const app = require('./app');

const port = Number(process.env.PORT) || 3000;

app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});
```

Required packages:

```bash
npm install helmet express-rate-limit
```

