Even though this is sample data, in a real app this would be sensitive user information. It should not be public unless intentionally designed that way.

### Risk

Unauthenticated users can retrieve user data. This is a classic broken access control issue.

### Recommendation

Require authentication for `/users`.

Example using JWT-based authentication:

```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.slice('Bearer '.length);

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;
    return next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

app.get('/users', authenticate, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

Also make sure `JWT_SECRET` is strong and stored in environment variables, not committed to source control.

