# Higher-Security Authentication Example Using JWT

For a production API, a static bearer token may not be enough. JWT or OAuth/OIDC is usually better.

Example using `jsonwebtoken`:

```bash
npm install jsonwebtoken
```

```js
const jwt = require('jsonwebtoken');

function requireJwt(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const token = authHeader.slice('Bearer '.length);

  try {
    req.user = jwt.verify(token, process.env.JWT_PUBLIC_OR_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}
```

Role check:

```js
function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || !Array.isArray(req.user.roles) || !req.user.roles.includes(role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    next();
  };
}
```

Usage:

```js
app.get('/users', requireJwt, requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

