# Recommended hardened version of `app.js`

Here is a more secure baseline version:

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

app.disable('x-powered-by');

app.use(helmet());

app.use(express.json({ limit: '100kb' }));

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests' },
});

app.use(apiLimiter);

function requireApiKey(req, res, next) {
  const configuredApiKey = process.env.API_KEY;

  if (!configuredApiKey) {
    return res.status(500).json({ error: 'Authentication is not configured' });
  }

  const providedApiKey = req.get('x-api-key');

  if (!providedApiKey || providedApiKey !== configuredApiKey) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  console.error(err);

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
  });
});

if (require.main === module) {
  const port = process.env.PORT || 3000;

  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;
```

Required packages:

```bash
npm install helmet express-rate-limit
```

Run with:

```bash
API_KEY='replace-with-long-random-secret' PORT=3000 node app.js
```

